# Each lesson: the dialogue/text (image from the book), vocabulary, comprehension, grammar, practice (with answers), speaking & writing.
BOOK = "ANG_6ACDO"


def F(page, y0, y1, x0=0.06, x1=0.94, cap=""):
    return {"page": page, "rect": [x0, y0, x1, y1], "caption": cap}


def E(title, pages, figs, objectives, intro, summary, points, vocab, qa, grammar, practice, speak, write, tf=None, kind="Dialogue", note=None):
    board = []
    for i, f in enumerate(figs):
        board.append({"h": kind + (f" ({i+1}/{len(figs)})" if len(figs) > 1 else ""), "lines": [], "fig": f})
    board.append({"h": "Vocabulary", "lines": [], "table": [["Word", "Meaning"]] + [list(x) for x in vocab]})
    board.append({"h": "Comprehension", "lines": [], "table": [["Question", "Answer"]] + [list(x) for x in qa]})
    if tf:
        board.append({"h": "True or False", "lines": [], "table": [["Statement", "Answer"]] + [list(x) for x in tf]})
    board.append({"h": "Grammar", "lines": grammar[0], **({"table": grammar[1]} if len(grammar) > 1 else {})})
    board.append({"h": "Practice (answers)", "lines": [], "table": [["Exercise", "Answer"]] + [list(x) for x in practice]})
    if note:
        board.append({"h": "Note", "lines": note})
    board.append({"h": "Speaking & writing", "lines": ["Speaking: " + speak, "Writing: " + write]})
    q, a = qa[0]
    return {"title": title, "match": [title], "pages": pages, "objectives": objectives, "intro": intro,
            "summary": summary, "points": points, "application": {"q": q, "a": a}, "board": board}


